mutations.find:
fn("log", (frame, a) => {
  ctx.onLog?.({ scope: scopePathString(frame.keys.path), values: a });
  return null;
}, "all"),

mutations.replace:
fn("log", (frame, a) => {
  a.forEach((v, i) => {
    if (typeof v === "function") throw new RuntimeFault("L4016", `log: value ${i + 1} is a function`);
  });
  ctx.onLog?.({ scope: scopePathString(frame.keys.path), values: a });
  return null;
}, "all"),
